void balloon_reclaim(vm_t *vm){
  while (deficit(vm) > 0){
    page_t *p = pop_free_vm(vm);
    if (!p) break;
    if (cmpxchg(&p->refcnt, 1, 0))
      reclaim_to_buddy(p);
    dec_deficit(vm);
